  "article": "<header class=\"sticky top-0 z-50 border-b bg-white\">\r\n    <div class=\"mx-auto flex h-16 max-w-7xl items-center justify-between px-4\">\r\n      <a href=\"/\" class=\"text-xl font-bold text-primary\">宏達升學教育機構</a>\r\n      <nav class=\"hidden md:flex items-center gap-6\">\r\n        <a href=\"/news\" class=\"text-primary font-medium\">最新消息</a>\r\n        <a href=\"/courses\" class=\"text-gray-600 hover:text-primary\">課程列表</a>\r\n        <a href=\"/\" class=\"btn-primary\">回首頁</a>\r\n      </nav>\r\n    </div>\r\n  </header>\r\n\r\n  <main class=\"mx-auto max-w-3xl flex-1 px-4 py-8\">\r\n    <article>\r\n      <span class=\"text-primary\">升學</span>\r\n      <h1 class=\"mt-2 text-3xl font-bold\">學測準備與讀書計畫</h1>\r\n      <p class=\"mt-2 text-gray-500\">2025-03-10</p>\r\n      <div class=\"relative mt-6 aspect-video overflow-hidden rounded-xl bg-gray-200\">\r\n        <img src=\"https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=800&h=450&fit=crop\" alt=\"\" class=\"h-full w-full object-cover\" />\r\n      </div>\r\n      <div class=\"prose mt-8 max-w-none\">\r\n        <p>宏達升學教育機構長期陪伴大台南學子衝刺學測，本文分享如何安排讀書計畫與各科準備要領。（完整文章內容可由 CMS 或後端提供。）</p>\r\n      </div>\r\n    </article>\r\n    <section class=\"mt-12 border-t pt-8\">\r\n      <h2 class=\"section-title mb-4\">相關課程推薦</h2>\r\n      <div class=\"grid gap-4 sm:grid-cols-3\">\r\n        <a href=\"/course-detail?slug=gsat-all\" class=\"rounded-lg border p-4 hover:border-primary\"><h3 class=\"font-medium\">學測全科班</h3><p class=\"text-sm text-primary\">洽詢報名</p></a>\r\n        <a href=\"/course-detail?slug=med-class\" class=\"rounded-lg border p-4 hover:border-primary\"><h3 class=\"font-medium\">醫科班</h3><p class=\"text-sm text-primary\">洽詢報名</p></a>\r\n        <a href=\"/course-detail?slug=junior-high\" class=\"rounded-lg border p-4 hover:border-primary\"><h3 class=\"font-medium\">國中會考班</h3><p class=\"text-sm text-primary\">洽詢報名</p></a>\r\n      </div>\r\n    </section>\r\n    <p class=\"mt-6\"><a href=\"/news\" class=\"text-primary hover:underline\">← 返回文章列表</a></p>\r\n  </main>\r\n\r\n  <footer class=\"border-t bg-gray-50 py-8\">\r\n    <div class=\"mx-auto max-w-7xl px-4 text-sm text-gray-500\">\r\n      <p>宏達補習班 · 臺南市中西區中正路88號7樓 · 電話：(06) 2201833</p>\r\n    </div>\r\n  </footer>",
  "cart": "<header class=\"sticky top-0 z-50 border-b bg-white\">\r\n    <div class=\"mx-auto flex h-16 max-w-7xl items-center justify-between px-4\">\r\n      <a href=\"/\" class=\"text-xl font-bold text-primary\">宏達升學教育機構</a>\r\n      <nav class=\"hidden md:flex items-center gap-6\">\r\n        <a href=\"/courses\" class=\"text-gray-600 hover:text-primary\">課程列表</a>\r\n        <a href=\"/cart\" class=\"text-primary font-medium\">購物車</a>\r\n        <a href=\"/login\" class=\"btn-primary\">會員登入</a>\r\n      </nav>\r\n    </div>\r\n  </header>\r\n\r\n  <main class=\"mx-auto max-w-4xl flex-1 px-4 py-8\">\r\n    <h1 class=\"section-title mb-6\">購物車</h1>\r\n    <div id=\"cart-empty\" class=\"rounded-xl border bg-gray-50 p-12 text-center hidden\">\r\n      <p class=\"text-gray-600\">購物車是空的</p>\r\n      <a href=\"/courses\" class=\"btn-primary mt-4 inline-block\">去選課</a>\r\n    </div>\r\n    <div id=\"cart-list\" class=\"space-y-4 hidden\">\r\n      <!-- 由 JS 或手動維護 -->\r\n    </div>\r\n    <div id=\"cart-summary\" class=\"mt-6 rounded-xl border bg-gray-50 p-4 hidden\">\r\n      <p class=\"text-lg font-medium\">付款方式：請於結帳頁選擇（綠界 / 其他）</p>\r\n      <p class=\"mt-2 text-sm text-gray-600\">未登入將導向會員登入後再結帳。</p>\r\n      <p class=\"mt-4 text-xl font-bold\">總計：NT$ <span id=\"cart-total\">0</span></p>\r\n      <a href=\"/checkout\" class=\"btn-primary mt-4 block text-center\">前往結帳</a>\r\n    </div>\r\n  </main>\r\n\r\n  <footer class=\"border-t bg-gray-50 py-8\">\r\n    <div class=\"mx-auto max-w-7xl px-4 text-sm text-gray-500\">\r\n      <p>宏達補習班 · 臺南市中西區中正路88號7樓 · 電話：(06) 2201833</p>\r\n    </div>\r\n  </footer>\r\n  \r\n  <script>\r\n    (function () {\r\n      var add = new URLSearchParams(location.search).get('add');\r\n      if (add) {\r\n        try {\r\n          var cart = localStorage.getItem('cart');\r\n          var arr = cart ? JSON.parse(cart) : [];\r\n          if (arr.indexOf(add) === -1) arr.push(add);\r\n          localStorage.setItem('cart', JSON.stringify(arr));\r\n          history.replaceState({}, '', 'cart.html');\r\n        } catch (e) {}\r\n      }\r\n      var cart = [];\r\n      try { cart = JSON.parse(localStorage.getItem('cart') || '[]'); } catch (e) {}\r\n      var courses = [\r\n        { id: '1', title: '日文發音入門', price: 1280, cover: 'https://images.unsplash.com/photo-1528360983277-13d401cdc186?w=400&h=225&fit=crop' },\r\n        { id: '2', title: '初級日語會話', price: 1980, cover: 'https://images.unsplash.com/photo-1528164344705-47542687000d?w=400&h=225&fit=crop' },\r\n        { id: '3', title: '中級閱讀與寫作', price: 2580, cover: 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?w=400&h=225&fit=crop' },\r\n        { id: '4', title: '商務日語', price: 3200, cover: 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?w=400&h=225&fit=crop' }\r\n      ];\r\n      var items = cart.map(function(id) { return courses.find(function(c) { return c.id === id; }); }).filter(Boolean);\r\n      var total = items.reduce(function(s, c) { return s + c.price; }, 0);\r\n      var emptyEl = document.getElementById('cart-empty');\r\n      var listEl = document.getElementById('cart-list');\r\n      var summaryEl = document.getElementById('cart-summary');\r\n      var totalEl = document.getElementById('cart-total');\r\n      if (items.length === 0) {\r\n        emptyEl.classList.remove('hidden');\r\n      } else {\r\n        listEl.classList.remove('hidden');\r\n        summaryEl.classList.remove('hidden');\r\n        totalEl.textContent = total;\r\n        listEl.innerHTML = items.map(function(c) {\r\n          return '<div class=\"flex gap-4 rounded-xl border bg-white p-4\">' +\r\n            '<img src=\"' + c.cover + '\" alt=\"\" class=\"h-24 w-40 flex-shrink-0 rounded object-cover\" />' +\r\n            '<div class=\"flex-1\"><h2 class=\"font-medium\">' + c.title + '</h2><p class=\"text-primary\">NT$ ' + c.price + '</p></div>' +\r\n            '<button type=\"button\" class=\"cart-remove text-red-600 hover:underline\" data-id=\"' + c.id + '\">移除</button></div>';\r\n        }).join('');\r\n        listEl.querySelectorAll('.cart-remove').forEach(function(btn) {\r\n          btn.addEventListener('click', function() {\r\n            var id = btn.getAttribute('data-id');\r\n            var arr = cart.filter(function(i) { return i !== id; });\r\n            localStorage.setItem('cart', JSON.stringify(arr));\r\n            location.reload();\r\n          });\r\n        });\r\n      }\r\n    })();\r\n  </script>",
